import sympy as sp
A = sp.Matrix([[1,2,-1],[3,8,1],[-2,2,9]])
U = A.copy()
for j in range(2):
    for i in range(j+1, 3):
        U[i,:] = U[i,:] - (U[i,j]/U[j,j])*U[j,:]   # no row interchanges
print(U.tolist(), U[2,2])                            # third pivot -5
opts = {"A": 7, "B": -10, "C": -5, "D": 19}
print([k for k,v in opts.items() if v == U[2,2]], A.det())  # ['C'] -10 (= product of pivots)

